// Hapus SEMUA karakter Markdown secara global (bukan per-pasangan)
// agar tidak ada karakter yg tidak tertutup -> Telegram error

function cleanForTelegram(text) {
  return text
    .replace(/\*/g, '')          // hapus SEMUA asterisk (* dan **)
    .replace(/`/g, '')           // hapus SEMUA backtick
    .replace(/~~/g, '')          // hapus strikethrough
    .replace(/^#{1,6}\s+/gm, '') // hapus heading markers
    .replace(/^>\s+/gm, '')      // hapus blockquote
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1') // link/image -> teks saja
    .replace(/\|/g, ' ')         // hapus pipe table
    .replace(/^[-=]{3,}$/gm, '---') // normalize separator
    .replace(/[ \t]+$/gm, '')    // trim trailing spaces per baris
    .trim();
}

const MAX_CONTENT = 3700;

return items.map(item => {
  const data = item.json;

  const candidateName = data.candidate_name
    || $('Loop Over Items').item.json.candidate_name
    || 'Kandidat';
  const position = data.position
    || $('Loop Over Items').item.json.position
    || 'Posisi';
  const fullText = data.text || '';

  const cleanText = cleanForTelegram(fullText);
  let content = cleanText;
  let isTruncated = false;

  if (cleanText.length > MAX_CONTENT) {
    content = cleanText.substring(0, MAX_CONTENT);
    const lastNewline = content.lastIndexOf('\n');
    if (lastNewline > MAX_CONTENT - 300) {
      content = content.substring(0, lastNewline);
    }
    isTruncated = true;
  }

  const header = `Pertanyaan Interview\nKandidat: ${candidateName}\nPosisi: ${position}\n${'-'.repeat(30)}\n\n`;
  const footer = isTruncated
    ? `\n\n[Pesan dipotong - total ${fullText.length} karakter, dikirim ${content.length} karakter]`
    : '';

  return {
    json: {
      ...data,
      candidate_name: candidateName,
      position: position,
      formatted_message: header + content + footer
    }
  };
});

